# L10 ------------------------------------------------------------------ ein, eine
MOOS = lambda: img('moosbach', 'Ein weißes Ortsschild „Moosbach“, daneben wenige Häuser, eine Kirche und Wiesen.', 'A white town sign “Moosbach”, next to it a few houses, a church and meadows.', 'Puting karatula ng bayan na “Moosbach”, sa tabi nito ay ilang bahay, simbahan at parang.')
lesson(10, L('ein, eine', 'ein, eine (a, an)', 'ein, eine (isang)'), ['ein'], [
    RULE('der / das → ein · die → eine', '„ein“ und „eine“ heißen „a/an“. Bei „der“ und „das“ sagt man „ein“, bei „die“ sagt man „eine“. Man hört die Endung -e nur bei „die“.',
         '“ein” and “eine” mean “a/an”. With “der” and “das” you say “ein”, with “die” you say “eine”. You only hear the ending -e with “die”.',
         'Ang “ein” at “eine” ay “isang”. Sa “der” at “das”, “ein” ang sinasabi; sa “die”, “eine”. Ang dulong -e ay naririnig lang sa “die”.',
         ['der Mensch → ein Mensch', 'das Dorf → ein Dorf', 'die Stadt → eine Stadt']),
    RULE('Neu: ein/eine · bekannt: der/die/das', 'Wenn etwas neu ist, sagt man „ein/eine“. Wenn man es schon kennt, sagt man „der/die/das“. Zuerst: „Das ist eine Stadt.“ Danach: „Die Stadt heißt Graz.“',
         'When something is new, you say “ein/eine”. When you already know it, you say “der/die/das”. First: “Das ist eine Stadt.” Then: “Die Stadt heißt Graz.”',
         'Kapag bago ang bagay, “ein/eine” ang sinasabi. Kapag kilala mo na, “der/die/das”. Una: “Das ist eine Stadt.” Pagkatapos: “Die Stadt heißt Graz.”',
         ['Das ist eine Stadt. Die Stadt heißt Graz.', 'Das ist ein Dorf. Das Dorf heißt Moosbach.']),
    PHRASE('Was ist Graz? – Graz ist eine Stadt.', 'Mit „ist“ sagen Sie, was etwas ist. Moosbach ist ein Dorf. Österreich ist ein Land.',
           'With “ist” you say what something is. Moosbach is a village. Austria is a country.', 'Gamit ang “ist”, sasabihin mo kung ano ang isang bagay. Baryo ang Moosbach. Bansa ang Austria.'),
    PHRASE('ein Hobby · eine Sprache', 'Auch hier: das Hobby → ein Hobby, die Sprache → eine Sprache. Sie hören nur bei „die“ ein -e.',
           'Same here: das Hobby → ein Hobby, die Sprache → eine Sprache. You only hear -e with “die”.', 'Ganoon din dito: das Hobby → ein Hobby, die Sprache → eine Sprache. Ang -e ay naririnig lang sa “die”.'),
], [
    choice(X, 'lesen', L('Tom ist in Österreich. Er sieht ein Ortsschild. Schauen Sie das Bild an.', 'Tom is in Austria and sees a town sign. Look at the picture: only a few houses and a church.', 'Nasa Austria si Tom at nakakita ng karatula ng bayan. Tingnan ang larawan: iilang bahay at isang simbahan lang.'),
           'Moosbach ist …', 'ein Dorf', ['eine Stadt', 'ein Land'],
           L('Richtig: „ein Dorf“. Man sieht nur wenige Häuser und eine Kirche. „das Dorf“ → „ein Dorf“. „eine Stadt“ hat viele Häuser. „ein Land“ ist viel größer, wie Österreich.',
             'Correct: “ein Dorf”. You only see a few houses and a church. “das Dorf” → “ein Dorf”. “eine Stadt” has many houses. “ein Land” is much bigger, like Austria.',
             'Tama: “ein Dorf”. Iilang bahay at isang simbahan lang ang makikita. “das Dorf” → “ein Dorf”. Ang “eine Stadt” ay maraming bahay. Ang “ein Land” ay mas malaki, tulad ng Austria.'),
           [G6, G2], R('ein', 'Dorf'), img=MOOS()),
    cloze(X, 'grammatikWortschatz', L('Anna schreibt im Kurs zwei Sätze. Ergänzen Sie.', 'Anna writes two sentences in the course. Complete them with the words below.', 'Sumusulat si Anna ng dalawang pangungusap sa kurso. Kumpletuhin gamit ang mga salita sa ibaba.'),
          'Graz ist {{1}} Stadt. Österreich ist {{2}} Land.', [['eine'], ['ein']],
          L('Richtig: „eine Stadt“ (die Stadt) und „ein Land“ (das Land). „die“ ist kein Wort für „a/an“.',
            'Correct: “eine Stadt” (die Stadt) and “ein Land” (das Land). “die” is not a word for “a/an”.',
            'Tama: “eine Stadt” (die Stadt) at “ein Land” (das Land). Ang “die” ay hindi salita para sa “isang”.'),
          [G6], R('ein', 'Stadt', 'Land'), bank=['eine', 'ein', 'die']),
    choice(X, 'grammatikWortschatz', L('Maria schreibt über Deutsch. Welches Wort passt?', 'Maria writes about German in the course. Which word fits?', 'Sumusulat si Maria tungkol sa German sa kurso. Aling salita ang bagay?'),
           'Deutsch ist … Sprache.', 'eine', ['ein', 'der'],
           L('Richtig: „Deutsch ist eine Sprache.“ „die Sprache“ → „eine Sprache“. „ein“ gehört zu „der/das“. „der“ ist kein Wort für „a/an“.',
             'Correct: “Deutsch ist eine Sprache.” “die Sprache” → “eine Sprache”. “ein” goes with “der/das”. “der” is not a word for “a/an”.',
             'Tama: “Deutsch ist eine Sprache.” “die Sprache” → “eine Sprache”. Ang “ein” ay para sa “der/das”. Ang “der” ay hindi salita para sa “isang”.'),
           [G6], R('ein', 'Sprache')),
    choice(X, 'lesen', L('Anna liest einen kurzen Text im Kurs.', 'Anna reads a short text in the course. What is Wien?', 'Binabasa ni Anna ang maikling teksto sa kurso. Ano ang Wien?'),
           'Wien ist eine Stadt. Moosbach ist ein Dorf. – Was ist Wien?', 'eine Stadt', ['ein Dorf', 'ein Land'],
           L('Richtig: „eine Stadt“. Der Text sagt: „Wien ist eine Stadt.“ „ein Dorf“ ist Moosbach. „ein Land“ steht nicht im Text.',
             'Correct: “eine Stadt”. The text says: “Wien ist eine Stadt.” “ein Dorf” is Moosbach. “ein Land” is not in the text.',
             'Tama: “eine Stadt”. Sabi ng teksto: “Wien ist eine Stadt.” Ang “ein Dorf” ay ang Moosbach. Wala sa teksto ang “ein Land”.'),
           [G6], R('Stadt', 'Dorf')),
    choice(X, 'grammatikWortschatz', L('Tom spricht im Kurs über Hobbys.', 'Tom talks about hobbies in the course. Which word fits?', 'Nagsasalita si Tom tungkol sa mga libangan sa kurso. Aling salita ang bagay?'),
           'Tom hat … Hobby.', 'ein', ['eine', 'die'],
           L('Richtig: „Tom hat ein Hobby.“ „das Hobby“ → „ein Hobby“. „eine“ gehört zu „die“, und „die“ ist kein Wort für „a/an“.',
             'Correct: “Tom hat ein Hobby.” “das Hobby” → “ein Hobby”. “eine” goes with “die”, and “die” is not a word for “a/an”.',
             'Tama: “Tom hat ein Hobby.” “das Hobby” → “ein Hobby”. Ang “eine” ay para sa “die”, at ang “die” ay hindi salita para sa “isang”.'),
           [G6], R('ein', 'Hobby')),
    cloze(X, 'grammatikWortschatz', L('Maria zeigt Anna eine Adresse im Kurs. Ergänzen Sie den Text.', 'Maria shows Anna an address in the course. Complete the text with the words below.', 'Ipinakita ni Maria kay Anna ang isang address sa kurso. Kumpletuhin ang teksto gamit ang mga salita sa ibaba.'),
          'Das ist {{1}} Adresse. {{2}} Adresse ist Hauptstraße 12.', [['eine'], ['Die']],
          L('Richtig: Zuerst neu: „eine Adresse“. Danach ist sie bekannt: „Die Adresse“. „Der“ passt nicht zu „Adresse“ (die Adresse).',
            'Correct: first it is new: “eine Adresse”. Then it is known: “Die Adresse”. “Der” does not fit “Adresse” (die Adresse).',
            'Tama: Una, bago: “eine Adresse”. Pagkatapos, kilala na: “Die Adresse”. Hindi bagay ang “Der” sa “Adresse” (die Adresse).'),
          [G6], R('ein', 'die', 'Adresse'), bank=['eine', 'Die', 'Der']),
    choice(X, 'hoeren', L('Tom zeigt ein Bild aus Österreich. Hören Sie.', 'Tom shows a picture from Austria in the course. Listen.', 'Nagpapakita si Tom ng larawan mula sa Austria sa kurso. Makinig.'),
           'Was ist Moosbach?', 'ein Dorf', ['eine Stadt', 'ein Land'],
           L('Sie hören: „Das ist Moosbach. Das ist ein Dorf.“ „das Dorf“ → „ein Dorf“. „eine Stadt“ und „ein Land“ sagt Tom nicht.',
             'You hear: “Das ist Moosbach. Das ist ein Dorf.” “das Dorf” → “ein Dorf”. Tom does not say “eine Stadt” or “ein Land”.',
             'Naririnig mo: “Das ist Moosbach. Das ist ein Dorf.” “das Dorf” → “ein Dorf”. Hindi sinabi ni Tom ang “eine Stadt” o “ein Land”.'),
           [G6], R('ein', 'Dorf'), audio='Das ist Moosbach. Das ist ein Dorf.'),
], intro=INTRO(
    L('Tom sagt im Kurs: „Das ist eine Stadt. Das ist ein Dorf.“', 'In the course Tom talks about places in Austria and says: “Das ist eine Stadt. Das ist ein Dorf.”', 'Sa kurso, nagsasalita si Tom tungkol sa mga lugar sa Austria at sinasabi: “Das ist eine Stadt. Das ist ein Dorf.”'),
    L('sagen, was etwas ist: „Graz ist eine Stadt.“ „Moosbach ist ein Dorf.“', 'say what something is: “Graz ist eine Stadt.” “Moosbach ist ein Dorf.”', 'sabihin kung ano ang isang bagay: “Graz ist eine Stadt.” “Moosbach ist ein Dorf.”')))

# L11 ------------------------------------------------------------------ suchen, finden, geben, nehmen
SUCHEN = lambda: img('suchen', 'Maria hält eine Karte und fragt etwas. Daneben steht ein Straßenschild.', 'Maria holds a map and asks something. A street sign stands next to her.', 'May hawak na mapa si Maria at nagtatanong. May karatula ng kalye sa tabi.')
lesson(11, L('suchen, finden, geben, nehmen', 'look for, find, give, take', 'maghanap, makahanap, magbigay, kumuha'), ['suchen', 'finden', 'geben', 'nehmen'], [
    PHRASE('Entschuldigung, ich suche die Bahnhofstraße.', 'So fragen Sie höflich nach dem Weg. „Entschuldigung“ am Anfang ist höflich. Dann: „Wo ist die Bahnhofstraße?“',
           'This is how you politely ask for the way. “Entschuldigung” at the start is polite. Then: “Wo ist die Bahnhofstraße?”', 'Ganito magalang na magtanong ng daan. Magalang ang “Entschuldigung” sa simula. Pagkatapos: “Wo ist die Bahnhofstraße?”'),
    RULE('suchen · finden: regelmäßig', 'ich suche, du suchst, er sucht – und ich finde, du findest, er findet. Bei „finden“ steht vor -st und -t ein -e-: findest, findet. Sonst kann man es nicht gut sprechen.',
         'ich suche, du suchst, er sucht – and ich finde, du findest, er findet. With “finden” an -e- comes before -st and -t: findest, findet. Otherwise it is hard to pronounce.',
         'ich suche, du suchst, er sucht – at ich finde, du findest, er findet. Sa “finden”, may -e- bago ang -st at -t: findest, findet. Kung hindi, mahirap bigkasin.',
         ['Ich suche die Straße.', 'Du findest die Adresse.', 'Maria findet die Straße nicht.']),
    RULE('suchen ≠ finden', '„Suchen“ heißt: Ich bin noch dabei. „Finden“ heißt: Ich habe es. Wer eine Sache nicht findet, sucht weiter. Man sagt: „Ich suche die Adresse. Ich finde sie nicht.“',
         '“Suchen” means: I am still looking. “Finden” means: I have it. If you do not find something, you keep looking. You say: “Ich suche die Adresse. Ich finde sie nicht.”',
         'Ang “suchen” ay: naghahanap pa ako. Ang “finden” ay: nakita ko na. Kapag hindi mo mahanap, patuloy kang maghahanap. Sinasabi: “Ich suche die Adresse. Ich finde sie nicht.”',
         ['Ich suche die Adresse.', 'Ich finde die Adresse nicht.', 'Jetzt finde ich die Adresse.']),
    RULE('geben · nehmen: e → i bei du und er/sie', 'Wie bei „sprechen“ ändert sich der Vokal: ich gebe, du gibst, er gibt – ich nehme, du nimmst, er nimmt. Bei „nehmen“ ändert sich auch der Konsonant: nehm- → nimm-.',
         'Like “sprechen” the vowel changes: ich gebe, du gibst, er gibt – ich nehme, du nimmst, er nimmt. With “nehmen” the consonant changes too: nehm- → nimm-.',
         'Tulad ng “sprechen”, nagbabago ang vowel: ich gebe, du gibst, er gibt – ich nehme, du nimmst, er nimmt. Sa “nehmen”, nagbabago rin ang consonant: nehm- → nimm-.',
         ['Du gibst mir die Adresse.', 'Anna gibt Tom die Adresse.', 'Tom nimmt die Adresse.']),
    PHRASE('Geben Sie mir bitte die Adresse.', 'So bitten Sie höflich um etwas: „Geben Sie mir bitte …“ Das Verb steht am Anfang, dann „Sie“.',
           'This is how you politely ask for something: “Geben Sie mir bitte …” The verb comes first, then “Sie”.', 'Ganito magalang na humiling ng isang bagay: “Geben Sie mir bitte …” Una ang verb, tapos “Sie”.'),
], [
    choice(X, 'lesen', L('Maria ist in Graz und hat eine Karte. Schauen Sie das Bild an.', 'Maria is in Graz and has a map. Look at the picture: she asks someone.', 'Nasa Graz si Maria at may mapa. Tingnan ang larawan: may tinatanong siya.'),
           'Was sucht Maria?', 'die Bahnhofstraße', ['die Hauptstraße', 'die Adresse'],
           L('Richtig: die Bahnhofstraße. Maria fragt: „Wo ist die Bahnhofstraße?“ Das Schild neben ihr zeigt die Hauptstraße – das ist eine andere Straße. „die Adresse“ steht nicht im Bild.',
             'Correct: die Bahnhofstraße. Maria asks: “Wo ist die Bahnhofstraße?” The sign next to her shows Hauptstraße – that is a different street. “die Adresse” is not in the picture.',
             'Tama: die Bahnhofstraße. Tanong ni Maria: “Wo ist die Bahnhofstraße?” Hauptstraße ang nasa karatula sa tabi niya – ibang kalye iyon. Wala sa larawan ang “die Adresse”.'),
           [G7, G2], R('suchen', 'Straße'), img=SUCHEN()),
    cloze(X, 'grammatikWortschatz', L('Maria spricht mit Jose in Graz. Ergänzen Sie die Verben.', 'Maria talks to Jose in Graz. Complete the verbs.', 'Nag-uusap sina Maria at Jose sa Graz. Kumpletuhin ang mga verb.'),
          'Maria: Ich {{1}} die Bahnhofstraße. Findest du die Straße?\nJose: Nein, ich {{2}} sie nicht. Aber Anna {{3}} mir die Adresse.', [['suche'], ['finde'], ['gibt']],
          L('Richtig: ich suche, ich finde, Anna gibt. Bei „ich“ endet das Verb auf -e, bei „Anna“ (= sie) auf -t – und „geben“ wird zu „gibt“ (e → i). „gebe“ passt nur zu „ich“.',
            'Correct: ich suche, ich finde, Anna gibt. With “ich” the verb ends in -e, with “Anna” (= sie) in -t – and “geben” becomes “gibt” (e → i). “gebe” only fits “ich”.',
            'Tama: ich suche, ich finde, Anna gibt. Sa “ich”, nagtatapos sa -e ang verb; sa “Anna” (= sie), sa -t – at ang “geben” ay nagiging “gibt” (e → i). Ang “gebe” ay para lang sa “ich”.'),
          [G7], R('suchen', 'finden', 'geben'), hints=['suchen', 'finden', 'geben']),
    choice(X, 'grammatikWortschatz', L('Maria gibt Tom einen Zettel mit der Adresse. Was macht Tom?', 'Maria gives Tom a slip of paper with the address. What does Tom do? Which verb form fits?', 'Binigyan ni Maria si Tom ng papel na may address. Ano ang ginagawa ni Tom? Aling anyo ng verb ang bagay?'),
           'Maria gibt Tom die Adresse. Tom … die Adresse.', 'nimmt', ['nehmt', 'nehmen'],
           L('Richtig: „Tom nimmt die Adresse.“ Bei „er/sie“ wird „nehmen“ zu „nimmt“ (e → i, hm → mm). „nehmt“ passt zu „ihr“, „nehmen“ zu „wir/Sie“.',
             'Correct: “Tom nimmt die Adresse.” With “er/sie” “nehmen” becomes “nimmt” (e → i, hm → mm). “nehmt” goes with “ihr”, “nehmen” with “wir/Sie”.',
             'Tama: “Tom nimmt die Adresse.” Sa “er/sie”, ang “nehmen” ay nagiging “nimmt” (e → i, hm → mm). Ang “nehmt” ay para sa “ihr”, ang “nehmen” sa “wir/Sie”.'),
           [G7], R('nehmen', 'geben')),
    choice(X, 'hoeren', L('Ein Mann steht in Graz auf der Straße. Hören Sie.', 'A man is standing in a street in Graz. Listen and choose what is correct.', 'May lalaking nakatayo sa kalye sa Graz. Makinig at piliin kung alin ang tama.'),
           'Was ist richtig?', 'Er sucht die Adresse.', ['Er gibt die Adresse.', 'Er findet die Adresse.'],
           L('Sie hören: „Entschuldigung, ich suche die Adresse Bergstraße fünf.“ Der Mann sucht – er hat die Adresse noch nicht. „geben“ und „finden“ sagt er nicht.',
             'You hear: “Entschuldigung, ich suche die Adresse Bergstraße fünf.” The man is looking – he does not have the address yet. He does not say “geben” or “finden”.',
             'Naririnig mo: “Entschuldigung, ich suche die Adresse Bergstraße fünf.” Naghahanap ang lalaki – wala pa siyang address. Hindi niya sinabi ang “geben” o “finden”.'),
           [G7], R('suchen'), audio='Entschuldigung, ich suche die Adresse Bergstraße fünf.'),
    choice(X, 'sprechen', L('Sie sind in Graz und suchen die Bahnhofstraße. Neben Ihnen steht ein Mann. Was sagen Sie? Wählen Sie, dann sagen Sie es laut.', 'You are in Graz and you are looking for the Bahnhofstraße. A man stands next to you. What do you say? Choose, then say it aloud.', 'Nasa Graz ka at hinahanap mo ang Bahnhofstraße. May lalaki sa tabi mo. Ano ang sasabihin mo? Pumili, tapos sabihin nang malakas.'),
           None, 'Entschuldigung, ich suche die Bahnhofstraße.', ['Entschuldigung, ich finde die Bahnhofstraße.', 'Entschuldigung, ich gebe die Bahnhofstraße.'],
           L('Richtig: „Entschuldigung, ich suche die Bahnhofstraße.“ Sie haben die Straße noch nicht – darum „suchen“. „finden“ sagt man, wenn man die Straße schon hat, „geben“ passt nicht zu einer Straße.',
             'Correct: “Entschuldigung, ich suche die Bahnhofstraße.” You do not have the street yet – so “suchen”. You say “finden” when you already have it; “geben” does not fit a street.',
             'Tama: “Entschuldigung, ich suche die Bahnhofstraße.” Wala ka pa sa kalye – kaya “suchen”. Sinasabi ang “finden” kapag nakita mo na; hindi bagay ang “geben” sa kalye.'),
           [G7, G2], R('suchen', 'Straße')),
    choice(X, 'sprechen', L('Frau Huber hat die Adresse von Lukas. Sie fragen Frau Huber. Was sagen Sie? Wählen Sie, dann sagen Sie es laut.', 'Mrs Huber has Lukas’s address. You want the address and ask Mrs Huber. What do you say? Choose, then say it aloud.', 'Hawak ni Frau Huber ang address ni Lukas. Gusto mo ang address at tinanong mo si Frau Huber. Ano ang sasabihin mo? Pumili, tapos sabihin nang malakas.'),
           None, 'Geben Sie mir bitte die Adresse.', ['Ich gebe Ihnen bitte die Adresse.', 'Sie gibst mir die Adresse.'],
           L('Richtig: „Geben Sie mir bitte die Adresse.“ Das ist die höfliche Bitte: Verb + Sie + mir. „Ich gebe Ihnen …“ sagt, dass Sie geben, nicht Frau Huber. „Sie gibst“ ist falsch: „gibst“ gehört zu „du“.',
             'Correct: “Geben Sie mir bitte die Adresse.” This is the polite request: verb + Sie + mir. “Ich gebe Ihnen …” says that you give, not Mrs Huber. “Sie gibst” is wrong: “gibst” goes with “du”.',
             'Tama: “Geben Sie mir bitte die Adresse.” Ito ang magalang na paghiling: verb + Sie + mir. Ang “Ich gebe Ihnen …” ay nagsasabing ikaw ang nagbibigay, hindi si Frau Huber. Mali ang “Sie gibst”: ang “gibst” ay para sa “du”.'),
           [G7], R('geben', 'mir')),
    choice(X, 'lesen', L('Jose und Anna sprechen im Kurs. Lesen Sie.', 'Jose and Anna talk in the course. Read the dialogue.', 'Nag-uusap sina Jose at Anna sa kurso. Basahin ang dialogo.'),
           'Jose: Ich suche die Adresse von Lukas. Ich finde sie nicht. – Anna: Hier, ich gebe dir die Adresse: Bergstraße 5. – Wer gibt Jose die Adresse?', 'Anna', ['Lukas', 'Tom'],
           L('Richtig: Anna. Sie sagt: „Ich gebe dir die Adresse.“ Lukas wohnt dort, aber er gibt die Adresse nicht. Tom kommt im Text nicht vor.',
             'Correct: Anna. She says: “Ich gebe dir die Adresse.” Lukas lives there, but he does not give the address. Tom is not in the text.',
             'Tama: Anna. Sinasabi niya: “Ich gebe dir die Adresse.” Doon nakatira si Lukas, pero hindi niya ibinibigay ang address. Wala si Tom sa teksto.'),
           [G7], R('geben', 'suchen', 'finden')),
], intro=INTRO(
    L('Maria ist in Graz und sucht die Bahnhofstraße. Sie findet die Straße nicht. Sie fragt einen Mann.', 'Maria is in Graz and looks for the Bahnhofstraße. She cannot find the street. She asks a man.', 'Nasa Graz si Maria at hinahanap ang Bahnhofstraße. Hindi niya mahanap ang kalye. Nagtanong siya sa isang lalaki.'),
    L('sagen, was Sie suchen und nicht finden, und höflich bitten: „Geben Sie mir bitte …“', 'say what you are looking for and cannot find, and ask politely: “Geben Sie mir bitte …”', 'sabihin kung ano ang hinahanap mo at hindi mahanap, at magalang na humiling: “Geben Sie mir bitte …”')))

# L12 ------------------------------------------------------------------ hobby, phone goodbye
ABS = lambda: img('abschied', 'Zwei Bilder. Bild 1: ein Mann hält ein Handy ans Ohr. Bild 2: zwei Personen stehen auf der Straße und winken.', 'Two pictures. Picture 1: a man holds a mobile phone to his ear. Picture 2: two people stand in the street and wave.', 'Dalawang larawan. Larawan 1: lalaking may hawak na cellphone sa tainga. Larawan 2: dalawang tao sa kalye na kumakaway.')
lesson(12, L('Hobby und Telefon', 'Hobby and phone', 'Libangan at telepono'), ['Hobby', 'auf Wiederhören'], [
    PHRASE('Auf Wiederhören!', 'So verabschieden Sie sich am Telefon. „hören“ = Sie hören die Person, aber Sie sehen sie nicht.',
           'This is how you say goodbye on the phone. “hören” = you hear the person, but you do not see them.', 'Ganito magpaalam sa telepono. “hören” = naririnig mo ang tao pero hindi mo siya nakikita.'),
    RULE('Telefon: Auf Wiederhören! · Persönlich: Auf Wiedersehen!', 'Am Telefon hört man sich nur: „Auf Wiederhören!“ Wenn man sich sieht, sagt man: „Auf Wiedersehen!“ Der Unterschied steht schon im Wort: hören – sehen.',
         'On the phone you only hear each other: “Auf Wiederhören!” When you see each other, you say: “Auf Wiedersehen!” The difference is in the word: hören – sehen.',
         'Sa telepono, naririnig lang ninyo ang isa’t isa: “Auf Wiederhören!” Kapag nagkikita kayo: “Auf Wiedersehen!” Nasa salita na ang pagkakaiba: hören – sehen.',
         ['Danke, Frau Huber. Auf Wiederhören!', 'Danke, Frau Huber. Auf Wiedersehen!']),
    PHRASE('Tschüss! · Servus!', 'Mit Freunden sagt man „Tschüss!“ oder „Servus!“ – am Telefon und persönlich. „Servus“ kann in Österreich „Hallo“ und „Tschüss“ heißen.',
           'With friends you say “Tschüss!” or “Servus!” – on the phone and in person. In Austria “Servus” can mean both “hello” and “bye”.', 'Sa kaibigan, “Tschüss!” o “Servus!” ang sinasabi – sa telepono at harapan. Sa Austria, ang “Servus” ay puwedeng “hello” at “paalam”.'),
    RULE('das Hobby – die Hobbys', 'Der Plural von „Hobby“ ist „Hobbys“ (nicht „Hobbies“ wie im Englischen). „Was ist Ihr Hobby?“ – „Mein Hobby ist Deutsch.“',
         'The plural of “Hobby” is “Hobbys” (not “Hobbies” as in English). “Was ist Ihr Hobby?” – “Mein Hobby ist Deutsch.”', 'Ang plural ng “Hobby” ay “Hobbys” (hindi “Hobbies” tulad sa English). “Was ist Ihr Hobby?” – “Mein Hobby ist Deutsch.”',
         ['Was ist Ihr Hobby?', 'Mein Hobby ist Deutsch.', 'Tom und Jose haben zwei Hobbys.']),
    CULTURE('Am Telefon: der Name', 'Am Telefon sagen viele Menschen in Österreich zuerst den Familiennamen: „Huber.“ Dann: „Grüß Gott, hier ist Anna Huber.“',
            'On the phone many people in Austria first say their family name: “Huber.” Then: “Grüß Gott, hier ist Anna Huber.”', 'Sa telepono, maraming tao sa Austria ang unang nagsasabi ng apelyido: “Huber.” Pagkatapos: “Grüß Gott, hier ist Anna Huber.”'),
], [
    choice(X, 'sprechen', L('Tom telefoniert mit Anna. Das Gespräch ist zu Ende. Schauen Sie Nummer 1 an.', 'Tom is on the phone with Anna. The conversation is over. Look at picture 1.', 'Kausap ni Tom si Anna sa telepono. Tapos na ang usapan. Tingnan ang larawan 1.'),
           'Nummer 1: Was sagt Tom zu Anna?', 'Auf Wiederhören!', ['Auf Wiedersehen!', 'Guten Morgen!'],
           L('Richtig: „Auf Wiederhören!“ Tom spricht am Telefon, Anna sieht er nicht. „Auf Wiedersehen“ sagt man, wenn man sich sieht. „Guten Morgen“ ist ein Gruß am Anfang, nicht am Ende.',
             'Correct: “Auf Wiederhören!” Tom is on the phone, he does not see Anna. You say “Auf Wiedersehen” when you see each other. “Guten Morgen” is a greeting at the start, not at the end.',
             'Tama: “Auf Wiederhören!” Nasa telepono si Tom, hindi niya nakikita si Anna. Ang “Auf Wiedersehen” ay kapag nagkikita kayo. Ang “Guten Morgen” ay bati sa simula, hindi sa dulo.'),
           [G4], R('auf Wiederhören'), img=ABS()),
    choice(X, 'sprechen', L('Anna und Jose sind auf der Straße. Jetzt gehen sie. Schauen Sie Nummer 2 an.', 'Anna and Jose meet in the street and now they leave. Look at picture 2.', 'Nagkita sina Anna at Jose sa kalye at aalis na sila. Tingnan ang larawan 2.'),
           'Nummer 2: Was sagen Anna und Jose?', 'Auf Wiedersehen!', ['Auf Wiederhören!', 'Gute Nacht!'],
           L('Richtig: „Auf Wiedersehen!“ Die beiden stehen zusammen auf der Straße und sehen sich. „Auf Wiederhören“ ist für das Telefon. „Gute Nacht“ sagt man abends, wenn man schlafen geht.',
             'Correct: “Auf Wiedersehen!” The two stand together in the street and see each other. “Auf Wiederhören” is for the phone. You say “Gute Nacht” in the evening, when you go to sleep.',
             'Tama: “Auf Wiedersehen!” Magkasama ang dalawa sa kalye at nagkikita. Ang “Auf Wiederhören” ay para sa telepono. Ang “Gute Nacht” ay sinasabi sa gabi kapag matutulog.'),
           [G4], R('auf Wiedersehen'), img=ABS()),
    cloze(X, 'grammatikWortschatz', L('Tom und Anna telefonieren. Tom sagt am Ende etwas. Ergänzen Sie.', 'Tom and Anna are on the phone. At the end Tom says something. Complete the sentence with the words below.', 'Nag-uusap sina Tom at Anna sa telepono. Sa dulo, may sinasabi si Tom. Kumpletuhin ang pangungusap gamit ang mga salita sa ibaba.'),
          'Tom: Danke, Anna! Auf {{1}}!', [['Wiederhören']],
          L('Richtig: „Auf Wiederhören!“ Tom und Anna telefonieren – sie hören sich nur. „Wiedersehen“ ist für Menschen, die sich sehen. „Wiederholen“ ist ein anderes Wort („noch einmal sagen“).',
            'Correct: “Auf Wiederhören!” Tom and Anna are on the phone – they only hear each other. “Wiedersehen” is for people who see each other. “Wiederholen” is a different word (“say again”).',
            'Tama: “Auf Wiederhören!” Nasa telepono sina Tom at Anna – naririnig lang nila ang isa’t isa. Ang “Wiedersehen” ay para sa mga nagkikita. Ang “Wiederholen” ay ibang salita (“sabihin muli”).'),
          [G4], R('auf Wiederhören', 'wiederholen'), bank=['Wiederhören', 'Wiedersehen', 'Wiederholen']),
    choice(X, 'hoeren', L('Hören Sie Herrn Novak und Frau Huber.', 'Listen to Mr Novak and Mrs Huber. How are they talking to each other?', 'Pakinggan ang dalawang tao. Paano sila nag-uusap?'),
           'Was ist richtig?', 'Frau Huber und Herr Novak sprechen am Telefon.', ['Frau Huber und Herr Novak sind zusammen.', 'Frau Huber und Herr Novak sind in Linz.'],
           L('Sie hören: „Danke, Frau Huber. Auf Wiederhören!“ „Auf Wiederhören“ sagt man nur am Telefon. Wenn die beiden zusammen wären, würden sie „Auf Wiedersehen“ sagen. Von Linz hört man nichts.',
             'You hear: “Danke, Frau Huber. Auf Wiederhören!” You only say “Auf Wiederhören” on the phone. If the two were together, they would say “Auf Wiedersehen”. Linz is not mentioned.',
             'Naririnig mo: “Danke, Frau Huber. Auf Wiederhören!” Sa telepono lang sinasabi ang “Auf Wiederhören”. Kung magkasama ang dalawa, “Auf Wiedersehen” ang sasabihin nila. Hindi nabanggit ang Linz.'),
           [G4], R('auf Wiederhören'), audio='Danke, Frau Huber. Auf Wiederhören! – Auf Wiederhören, Herr Novak!'),
    choice(X, 'sprechen', L('Der Deutschkurs ist zu Ende. Anna geht nach Hause. Sie sehen Anna. Was sagen Sie? Wählen Sie, dann sagen Sie es laut.', 'The German course is over. Anna goes home. You see Anna. What do you say? Choose, then say it aloud.', 'Tapos na ang kursong German. Uuwi na si Anna. Nakikita mo si Anna. Ano ang sasabihin mo? Pumili, tapos sabihin nang malakas.'),
           None, 'Auf Wiedersehen, Anna!', ['Auf Wiederhören, Anna!', 'Guten Morgen, Anna!'],
           L('Richtig: „Auf Wiedersehen, Anna!“ Sie sehen Anna – also „sehen“. „Auf Wiederhören“ ist für das Telefon. „Guten Morgen“ ist ein Gruß am Morgen, kein Abschied.',
             'Correct: “Auf Wiedersehen, Anna!” You see Anna – so “sehen”. “Auf Wiederhören” is for the phone. “Guten Morgen” is a morning greeting, not a goodbye.',
             'Tama: “Auf Wiedersehen, Anna!” Nakikita mo si Anna – kaya “sehen”. Ang “Auf Wiederhören” ay para sa telepono. Ang “Guten Morgen” ay bati sa umaga, hindi paalam.'),
           [G4], R('auf Wiedersehen')),
    choice(X, 'sprechen', L('Ein Mann im Kurs fragt Sie nach Ihrem Hobby. Ihr Hobby ist Deutsch. Was sagen Sie? Wählen Sie, dann sagen Sie es laut.', 'A man in the course asks you about your hobby. Your hobby is German. What do you say? Choose, then say it aloud.', 'Tinanong ka ng isang lalaki sa kurso tungkol sa libangan mo. German ang libangan mo. Ano ang sasabihin mo? Pumili, tapos sabihin nang malakas.'),
           'Mann: „Was ist Ihr Hobby?“', 'Mein Hobby ist Deutsch.', ['Meine Hobby ist Deutsch.', 'Ich bin Hobby Deutsch.'],
           L('Richtig: „Mein Hobby ist Deutsch.“ „das Hobby“ → „mein Hobby“. „Meine“ gehört zu „die“ (meine Sprache). Mit „Ich bin Hobby“ sagen Sie nicht, was Ihr Hobby ist.',
             'Correct: “Mein Hobby ist Deutsch.” “das Hobby” → “mein Hobby”. “Meine” goes with “die” (meine Sprache). With “Ich bin Hobby” you do not say what your hobby is.',
             'Tama: “Mein Hobby ist Deutsch.” “das Hobby” → “mein Hobby”. Ang “Meine” ay para sa “die” (meine Sprache). Sa “Ich bin Hobby”, hindi mo nasasabi kung ano ang libangan mo.'),
           [G6], R('Hobby')),
    choice(X, 'grammatikWortschatz', L('Jose und Tom sprechen im Kurs über Hobbys. Welche Mehrzahl ist richtig?', 'Jose and Tom talk about hobbies in the course. Which plural is correct?', 'Nag-uusap sina Jose at Tom tungkol sa mga libangan sa kurso. Aling plural ang tama?'),
           'Jose und Tom haben zwei …', 'Hobbys', ['Hobbies', 'Hobbyn'],
           L('Richtig: „zwei Hobbys“. Das Nomen „Hobby“ bekommt im Plural ein -s. „Hobbies“ ist die englische Form, „Hobbyn“ gibt es nicht.',
             'Correct: “zwei Hobbys”. The noun “Hobby” takes -s in the plural. “Hobbies” is the English form, “Hobbyn” does not exist.',
             'Tama: “zwei Hobbys”. Ang noun na “Hobby” ay nagdaragdag ng -s sa plural. Ang “Hobbies” ay anyong English; walang “Hobbyn”.'),
           [G6], R('Hobby', 'zwei')),
], intro=INTRO(
    L('Tom spricht am Telefon mit Anna. Am Ende sagt er: „Auf Wiederhören!“ Im Kurs sagt er: „Auf Wiedersehen!“', 'Tom is on the phone with Anna. At the end he says: “Auf Wiederhören!” In the course he says: “Auf Wiedersehen!”', 'Kausap ni Tom si Anna sa telepono. Sa dulo, sinasabi niya: “Auf Wiederhören!” Sa kurso, sinasabi niya: “Auf Wiedersehen!”'),
    L('am Telefon und persönlich richtig „Auf Wiederhören!“ und „Auf Wiedersehen!“ sagen und über Ihr Hobby sprechen.', 'say “Auf Wiederhören!” and “Auf Wiedersehen!” correctly on the phone and in person, and talk about your hobby.', 'sabihin nang tama ang “Auf Wiederhören!” at “Auf Wiedersehen!” sa telepono at harapan, at pag-usapan ang libangan mo.')))

# L13 ------------------------------------------------------------------ Austria basics (A1-WOW-19, A1-WOW-01; Q36)
AT = lambda: img('oesterreich', 'Österreich mit einem Stern für die Hauptstadt, eine Euro-Münze, die Flagge der EU und die Flagge von Österreich.', 'Austria with a star for the capital, a euro coin, the EU flag and the Austrian flag.', 'Austria na may bituin para sa kabisera, euro coin, bandila ng EU at ng Austria.')
EXPL = lambda de_, en, tl: L(de_ + ' Merksatz: Hauptstadt Wien, Geld Euro, Sprache Deutsch, seit 1995 in der EU.', en + ' Key facts: capital Vienna, money euro, language German, in the EU since 1995.', tl + ' Mahahalagang tala: kabisera Wien, pera euro, wika Deutsch, nasa EU mula 1995.')
lesson(13, L('Österreich kurz', 'Austria in brief', 'Austria sa madaling salita'), [], [
    PHRASE('Die Hauptstadt ist Wien.', 'Wien ist die größte Stadt und die Hauptstadt von Österreich. Graz und Linz sind auch Städte, aber nicht die Hauptstadt.',
           'Vienna is the biggest city and the capital of Austria. Graz and Linz are cities too, but not the capital.', 'Ang Wien ang pinakamalaking lungsod at kabisera ng Austria. Mga lungsod din ang Graz at Linz, pero hindi kabisera.'),
    PHRASE('Das Geld ist der Euro.', 'In Österreich zahlt man mit Euro und Cent. Ein Euro hat 100 Cent.', 'In Austria you pay with euros and cents. One euro has 100 cents.', 'Sa Austria, euro at cent ang pambayad. Ang isang euro ay 100 cent.'),
    PHRASE('Die Staatssprache ist Deutsch.', 'Auf dem Amt und in der Schule spricht man Deutsch. Deutsch hilft bei der Arbeit und im Alltag.', 'German is the language of offices and schools. German helps at work and in everyday life.', 'German ang wika ng opisina at paaralan. Nakakatulong ang German sa trabaho at araw-araw.'),
    PHRASE('Österreich ist seit 1995 in der EU.', 'EU = Europäische Union. Auch Deutschland ist in der EU. Die Schweiz ist nicht in der EU.', 'EU = European Union. Germany is in the EU too. Switzerland is not in the EU.', 'EU = European Union. Nasa EU rin ang Germany. Wala sa EU ang Switzerland.'),
], [
    choice(X, 'werte', L('Anna zeigt im Kurs ein Bild von Österreich. Das rote Zeichen auf der Karte ist Wien.', 'In the course Anna shows a picture of Austria. The red star on the map is Wien.', 'Sa kurso, nagpapakita si Anna ng larawan ng Austria. Ang pulang bituin sa mapa ay ang Wien.'),
           'Wien ist …', 'die Hauptstadt von Österreich', ['die Hauptstadt von Deutschland', 'die Hauptstadt von der Schweiz'], EXPL('Richtig: Wien ist die Hauptstadt von Österreich. Der Stern im Bild zeigt die Hauptstadt. Die Hauptstadt von Deutschland ist Berlin, die der Schweiz ist Bern.', 'Correct: Wien is the capital of Austria. The star in the picture marks the capital. The capital of Germany is Berlin, that of Switzerland is Bern.', 'Tama: ang Wien ay kabisera ng Austria. Ipinapakita ng bituin sa larawan ang kabisera. Ang kabisera ng Germany ay Berlin, ng Switzerland ay Bern.'), [G8], R('Österreich', 'Deutschland', 'Schweiz'), img=AT()),
    choice(X, 'werte', L('Anna bezahlt in einem Geschäft in Wien. Welches Geld nimmt sie?', 'Anna pays in a shop in Vienna. Which money does she use?', 'Nagbabayad si Anna sa tindahan sa Wien. Anong pera ang gamit niya?'),
           'Das Geld in Österreich ist …', 'der Euro', ['der Dollar', 'der Franken'], EXPL('Richtig: der Euro. In Österreich zahlt man mit Euro und Cent. Der Dollar gilt in den USA, der Franken in der Schweiz.', 'Correct: the euro. In Austria you pay with euros and cents. The dollar is used in the USA, the franc in Switzerland.', 'Tama: ang euro. Sa Austria, euro at cent ang pambayad. Ang dollar ay sa USA, ang franc ay sa Switzerland.'), [G8], R('Euro', 'Cent')),
    choice(X, 'werte', L('Jose fragt im Kurs: Welche Sprache spricht man am Amt in Österreich?', 'In the course Jose asks: which language do people speak at the office in Austria?', 'Sa kurso, nagtanong si Jose: anong wika ang ginagamit sa opisina sa Austria?'),
           'Die Staatssprache in Österreich ist …', 'Deutsch', ['Englisch', 'Tagalog'], EXPL('Richtig: Deutsch. Auf dem Amt und in der Schule spricht man Deutsch. Englisch und Tagalog sind keine Staatssprachen in Österreich.', 'Correct: German. At the office and in school people speak German. English and Tagalog are not official languages in Austria.', 'Tama: German. Sa opisina at paaralan, German ang ginagamit. Hindi opisyal na wika sa Austria ang English at Tagalog.'), [G8], R('Deutsch', 'Sprache')),
    choice(X, 'werte', L('Tom liest über Europa. Österreich ist ein Land in der EU.', 'Tom reads about Europe. Austria is a country in the EU. Since when?', 'Nagbabasa si Tom tungkol sa Europa. Ang Austria ay bansa sa EU. Mula kailan?'),
           'Österreich ist in der EU seit …', '1995', ['1985', '2004'], EXPL('Richtig: 1995. Seit 1995 ist Österreich in der EU. 1985 und 2004 sind falsch.', 'Correct: 1995. Austria has been in the EU since 1995. 1985 and 2004 are wrong.', 'Tama: 1995. Mula 1995 nasa EU ang Austria. Mali ang 1985 at 2004.'), [G8], R('Europa')),
    cloze(X, 'werte', L('Anna schreibt einen kurzen Text über Österreich. Ergänzen Sie ihn.', 'Anna writes a short text about Austria. Complete it with the words below.', 'Sumusulat si Anna ng maikling teksto tungkol sa Austria. Kumpletuhin ito gamit ang mga salita sa ibaba.'),
          'Österreich ist ein Land in {{1}}. Die Hauptstadt ist {{2}}. Das Geld ist der {{3}}.', [['Europa'], ['Wien'], ['Euro']],
          EXPL('Richtig: Österreich ist ein Land in Europa. Die Hauptstadt ist Wien (nicht Graz) und das Geld ist der Euro.', 'Correct: Austria is a country in Europe. The capital is Vienna (not Graz) and the money is the euro.', 'Tama: ang Austria ay bansa sa Europa. Ang kabisera ay Wien (hindi Graz) at ang pera ay euro.'),
          [G8], R('Europa', 'Euro'), bank=['Europa', 'Wien', 'Euro', 'Graz']),
    choice(X, 'werte', L('Sie hören Anna im Kurs. Hören Sie und wählen Sie, was richtig ist.', 'You hear Anna in the course. Listen and choose what is correct.', 'Naririnig mo si Anna sa kurso. Makinig at piliin kung alin ang tama.'),
           'Was ist richtig?', 'Anna wohnt in der Hauptstadt.', ['Anna wohnt in Graz.', 'Anna wohnt in der Schweiz.'],
           EXPL('Sie hören: „Ich bin Anna. Ich wohne in Wien. Wien ist die Hauptstadt von Österreich.“ Also wohnt Anna in der Hauptstadt. Von Graz und der Schweiz spricht sie nicht.', 'You hear: “Ich bin Anna. Ich wohne in Wien. Wien ist die Hauptstadt von Österreich.” So Anna lives in the capital. She does not talk about Graz or Switzerland.', 'Naririnig mo: “Ich bin Anna. Ich wohne in Wien. Wien ist die Hauptstadt von Österreich.” Kaya nakatira si Anna sa kabisera. Hindi niya binanggit ang Graz o ang Switzerland.'),
          [G8], R('wohnen', 'Stadt'), audio='Ich bin Anna. Ich wohne in Wien. Wien ist die Hauptstadt von Österreich.'),
], intro=INTRO(
    L('Im Deutschkurs sprechen Anna, Jose und Tom über Österreich. Sie lernen vier wichtige Dinge: Hauptstadt, Geld, Sprache und EU.', 'In the German course Anna, Jose and Tom talk about Austria. They learn four important things: capital, money, language and EU.', 'Sa kursong German, nag-uusap sina Anna, Jose at Tom tungkol sa Austria. Apat na mahalagang bagay ang natututunan nila: kabisera, pera, wika at EU.'),
    L('vier Dinge über Österreich sagen: Hauptstadt Wien, Geld Euro, Sprache Deutsch, in der EU seit 1995.', 'say four facts about Austria: capital Vienna, money euro, language German, in the EU since 1995.', 'sabihin ang apat na bagay tungkol sa Austria: kabisera Wien, pera euro, wika German, nasa EU mula 1995.')))

introduced = {r for l in lessons for r in l['introduces']}
print('not introduced:', [v['lemma'] for v in vocab if v['id'] not in introduced and v['id'] not in NO_CARD])
json.dump({'schemaVersion': 1, 'chapterId': CH, 'tlReviewStatus': 'machine', 'vocab': vocab, 'lessons': lessons}, open(f'{ROOT}/src/lib/content/a1-03.json', 'w'), ensure_ascii=False, indent='\t')
print(len(lessons), 'lessons', sum(len(l['items']) for l in lessons), 'items')
